const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels = {photo:'PNG 图像',note:'纯文本文稿',document:'PDF 文稿',word:'Word 文稿',folder:'文件夹',web:'网页',code:'Swift 源代码',audio:'WAV 音频',video:'QuickTime 影片',archive:'ZIP 归档',file:'数据文件',group:'收纳夹'};
