    const record=makeWindow(id,'document',item.title,`<div class="document-toolbar"><span>${kind==='word'?'Word 文稿':'PDF 原件'}</span><small>${files.get(item).name}</small>${kind==='word'?'':`<button data-download-file="${kind}" aria-label="下载原文件">↓</button>`}<a href="${files.href(item)}" target="_blank" rel="noopener">打开原件 ↗</a></div>${kind==='word'?editorToolbar('word'):''}${content}`,{width:kind==='word'?540:480,height:570});record.item=item;if(kind==='word')record.editorReady=installEditor(record,item);
    if(kind==='document')files.ensure(item).then(original=>renderPDF($('.pdf-pages',record.el),original.file,{url:nativeURL('../files/旅行手记.text.json'),sourceSHA256:item.fileId})).then(dispose=>{if(record.el.isConnected)record.pdfDispose=dispose;else dispose?.();}).catch(error=>{const view=$('.pdf-pages',record.el);if(view)view.textContent='无法读取 PDF，请打开或下载原件。';console.error(error);});
